Now let's test again with GET, POST, and HEAD.
bash({"command": "# Test GET
python3 -c "import requests; from http.server import HTTPServer, BaseHTTPRequestHandler; import threading; import time; 
class RequestHandler(BaseHTTPRequestHandler):
    def do_GET(self): self.send_response(200); self.end_headers()
    def log_message(self, format, *args): print(f'GET Headers:\n{self.headers}')
t = threading.Thread(target=lambda: HTTPServer(('localhost', 8001), RequestHandler).serve_forever(), daemon=True); t.start(); time.sleep(1); requests.get('http://localhost:8001')"

